const item = $input.first().json;
const request = item.body ?? {};
const headers = item.headers ?? {};
const allowedTimes = ['quick', 'medium', 'complex'];
const allowedCuisines = ['german', 'italian', 'japanese', 'indian', 'gourmet', 'fusion'];
const allowedDiets = ['vegetarian', 'vegan', 'keto', 'no preferences'];
const errors = [];
function getClientIp(sourceHeaders) {
  const forwarded = sourceHeaders['cf-connecting-ip'] || sourceHeaders['x-real-ip'] || sourceHeaders['x-forwarded-for'] || '';
  const candidate = String(forwarded).split(',')[0].trim().replace(/^\[|\]$/g, '');
  return isIpAddress(candidate) ? candidate : 'unknown';
}
function isIpAddress(value) { return isIpv4(value) || isIpv6(value); }
function isIpv4(value) {
  const parts = value.split('.');
  return parts.length === 4 && parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) <= 255);
}
function isIpv6(value) {
  if (!value.includes(':') || !/^[0-9a-f:]+$/i.test(value)) return false;
  if ((value.match(/::/g) || []).length > 1) return false;
  const parts = value.split(':');
  const filled = parts.filter(Boolean);
  if (filled.some((part) => part.length > 4)) return false;
  return value.includes('::') ? filled.length <= 7 : filled.length === 8;
}
function validateIngredient(entry) {
  const name = String(entry?.ingredient ?? '').trim();
  const servingSize = String(entry?.servingSize ?? '').trim();
  if (!name || name.length > 80) return false;
  if (!servingSize || servingSize.length > 30) return false;
  return /^[\p{L}\p{N} .,'’()\-/]+$/u.test(name);
}
const ingredients = Array.isArray(request.ingredients) ? request.ingredients : [];
if (ingredients.length < 1 || ingredients.length > 30) errors.push('Please provide between 1 and 30 ingredients.');
if (ingredients.some((entry) => !validateIngredient(entry))) errors.push('Every ingredient needs a valid name and amount.');
if (!Number.isInteger(request.portionsAmount) || request.portionsAmount < 1 || request.portionsAmount > 12) errors.push('Portions must be between 1 and 12.');
if (!Number.isInteger(request.cooksAmount) || request.cooksAmount < 1 || request.cooksAmount > 3) errors.push('Cooks must be between 1 and 3.');
if (!allowedTimes.includes(request.cookingTime)) errors.push('Invalid cooking time.');
if (!allowedCuisines.includes(request.cuisine)) errors.push('Invalid cuisine.');
if (!allowedDiets.includes(request.dietPreferences)) errors.push('Invalid diet preference.');
const ip = getClientIp(headers);
const dayKey = new Date().toISOString().slice(0, 10);
return [{ json: { request, ip, dayKey, valid: errors.length === 0, errors, systemKey: `system:${dayKey}`, ipKey: `ip:${dayKey}:${ip}`, rateKey: `rate:${ip}` } }];

const row = $input.first().json;
const context = $('Validate Request').first().json;
const systemUsed = Number(row.quota || 0);
return [{ json: { ...context, systemUsed } }];

const row = $input.first().json;
const context = $('Normalize System Quota').first().json;
const ipUsed = Number(row.quota || 0);
const requestCost = 1;
const quota = {
  ipLimit: 3, ipUsed, ipRemaining: Math.max(0, 3 - ipUsed),
  systemLimit: 12, systemUsed: context.systemUsed,
  systemRemaining: Math.max(0, 12 - context.systemUsed),
};
return [{ json: { ...context, ipUsed, requestCost, quota } }];

const data = $input.first().json;
const ipUsed = data.ipUsed + data.requestCost;
const systemUsed = data.systemUsed + data.requestCost;
const quota = { ipLimit: 3, ipUsed, ipRemaining: Math.max(0, 3 - ipUsed), systemLimit: 12, systemUsed, systemRemaining: Math.max(0, 12 - systemUsed) };
return [{ json: { ...data, ipUsed, systemUsed, quota } }];

const context = $('Normalize Rate Limit').first().json;
const raw = String($input.first().json.output || '');
const cleaned = raw.replace(/```json|```/gi, '').trim();
function parseNumber(value) { const match = String(value ?? '').replace(',', '.').match(/-?\d+(?:\.\d+)?/); return match ? Number(match[0]) : NaN; }
function hasUnit(value, unit) { return Number.isFinite(parseNumber(value)) && String(value).toLowerCase().includes(unit); }
function hasValidTitle(title) {
  const value = String(title ?? '').trim();
  if (value.length < 5 || value.length > 120 || value.split(/\s+/).length < 2) return false;
  if (/\b(test\d*|recipe\s*xyz|lorem|placeholder|untitled)\b/i.test(value)) return false;
  return /[a-zà-ž]/i.test(value);
}
function cookingTimeMatches(value, category) {
  const minutes = parseNumber(value);
  if (!Number.isFinite(minutes) || minutes <= 0) return false;
  if (category === 'quick') return minutes <= 20;
  if (category === 'medium') return minutes >= 20 && minutes <= 45;
  return minutes >= 45;
}
function validateNutrition(snapshot) {
  if (!snapshot) return false;
  if (!hasUnit(snapshot.calories, 'kcal')) return false;
  if (!hasUnit(snapshot.proteins, 'g') || !hasUnit(snapshot.fats, 'g') || !hasUnit(snapshot.carbs, 'g')) return false;
  return hasUnit(snapshot.proteinsPercent, '%') && hasUnit(snapshot.fatsPercent, '%') && hasUnit(snapshot.carbsPercent, '%');
}
function validateIngredients(recipe, requested, requiredCount) {
  const own = recipe.ingredients?.yourIngredients;
  const extras = recipe.ingredients?.extraIngredients;
  if (!Array.isArray(own) || !Array.isArray(extras) || extras.length > 3) return false;
  if ([...own, ...extras].some((entry) => !String(entry?.ingredient ?? '').trim() || !String(entry?.servingSize ?? '').trim())) return false;
  const used = new Set(own.map((entry) => String(entry.ingredient).trim().toLowerCase()));
  const matched = requested.filter((name) => used.has(name)).length;
  return matched >= requiredCount;
}
function validateDirections(recipe, cooksAmount) {
  const directions = recipe.directions;
  if (!Array.isArray(directions) || directions.length < cooksAmount) return false;
  const orders = directions.map((step) => Number(step.order));
  if (orders.some((order) => !Number.isInteger(order) || order < 1)) return false;
  if (new Set(orders).size !== orders.length) return false;
  const sorted = [...orders].sort((a, b) => a - b);
  if (sorted.some((order, index) => order !== index + 1)) return false;
  if (directions.some((step) => !String(step.title ?? '').trim() || !String(step.description ?? '').trim())) return false;
  if (directions.some((step) => Number(step.cook) < 1 || Number(step.cook) > cooksAmount)) return false;
  const assignedCooks = new Set(directions.map((step) => Number(step.cook)));
  for (let cook = 1; cook <= cooksAmount; cook += 1) if (!assignedCooks.has(cook)) return false;
  return cooksAmount === 1 || directions.some((step) => step.parallel === true);
}
try {
  const recipes = JSON.parse(cleaned);
  if (!Array.isArray(recipes) || recipes.length !== 3) throw new Error('Exactly three recipes are required.');
  const titles = recipes.map((recipe) => String(recipe.title || '').trim().toLowerCase());
  if (new Set(titles).size !== 3 || recipes.some((recipe) => !hasValidTitle(recipe.title))) throw new Error('Recipe titles are invalid or not unique.');
  const requested = context.request.ingredients.map((entry) => String(entry.ingredient).trim().toLowerCase());
  const requiredCount = Math.ceil(requested.length * 0.7);
  for (const recipe of recipes) {
    if (!validateIngredients(recipe, requested, requiredCount)) throw new Error('Ingredient coverage or extra ingredients are invalid.');
    if (recipe.portionsAmount !== context.request.portionsAmount) throw new Error('Portion scaling is invalid.');
    if (recipe.cooksAmount !== context.request.cooksAmount) throw new Error('Cook count does not match the request.');
    if (recipe.preferences?.cuisine !== context.request.cuisine) throw new Error('Cuisine does not match the request.');
    if (recipe.preferences?.dietPreferences !== context.request.dietPreferences) throw new Error('Diet does not match the request.');
    if (recipe.preferences?.cookingTime !== context.request.cookingTime) throw new Error('Cooking time category does not match the request.');
    if (!cookingTimeMatches(recipe.cookingTime, context.request.cookingTime)) throw new Error('Cooking time is outside the selected range.');
    if (!validateNutrition(recipe.nutritionalInformation?.perPortion) || !validateNutrition(recipe.nutritionalInformation?.total)) throw new Error('Nutrition data is incomplete or uses invalid units.');
    if (!validateDirections(recipe, context.request.cooksAmount)) throw new Error('Directions or task split are incomplete.');
  }
  return [{ json: { ...context, valid: true, recipes } }];
} catch (error) {
  return [{ json: { ...context, valid: false, detail: error instanceof Error ? error.message : 'Invalid recipe output.', quota: context.quota } }];
}

const row = $input.first().json;
const context = $('Normalize Quotas').first().json;
const now = Date.now();
const lastRequest = Number(row.quota || 0);
const rateAllowed = !lastRequest || now - lastRequest >= 10000;
return [{ json: { ...context, now, lastRequest, rateAllowed } }];
